    # Find divider color: a color that forms full uniform rows and columns
    row_full = {}
    for i, row in enumerate(grid):
        if all(v == row[0] for v in row):
            row_full.setdefault(row[0], []).append(i)

    col_full = {}
    for j in range(w):
        v = grid[0][j]
        ok = True
        for i in range(h):
            if grid[i][j] != v:
                ok = False
                break
        if ok:
            col_full.setdefault(v, []).append(j)

    divider = None
    best = -1
    for c in set(row_full) | set(col_full):
        score = len(row_full.get(c, [])) + len(col_full.get(c, []))
        if len(row_full.get(c, [])) >= 1 and len(col_full.get(c, [])) >= 1 and score > best:
            best = score
            divider = c

    # Segment rows/cols into cell interiors separated by divider lines
    row_groups = []
    i = 0
    while i < h:
        if all(grid[i][j] == divider for j in range(w)):
            i += 1
        else:
            s = i
            while i < h and not all(grid[i][j] == divider for j in range(w)):
                i += 1
            row_groups.append((s, i - 1))

    col_groups = []
    j = 0
    while j < w:
        if all(grid[i][j] == divider for i in range(h)):
            j += 1
        else:
            s = j
            while j < w and not all(grid[i][j] == divider for i in range(h)):
                j += 1
            col_groups.append((s, j - 1))

    R, C = len(row_groups), len(col_groups)

    # Build cell-color matrix by majority color in each cell block
    cells = [[0] * C for _ in range(R)]
    for r, (r0, r1) in enumerate(row_groups):
        for c, (c0, c1) in enumerate(col_groups):
            counts = {}
            for i in range(r0, r1 + 1):
                for j in range(c0, c1 + 1):
                    v = grid[i][j]
                    counts[v] = counts.get(v, 0) + 1
            cells[r][c] = max(counts, key=counts.get)

    # Background is the most frequent non-divider cell color
    cell_counts = {}
    for row in cells:
        for v in row:
            if v != divider:
                cell_counts[v] = cell_counts.get(v, 0) + 1
    bg = max(cell_counts, key=cell_counts.get)

    colors = [c for c in cell_counts if c != bg]

    # Find motif: choose ordered pair (center, fill) with strongest local pattern
    best_pair = None
    best_offsets = None
    best_count = -1

    neigh = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if not (dr == 0 and dc == 0)]

    for center in colors:
        for fill in colors:
            if center == fill:
                continue
            for r in range(R):
                for c in range(C):
                    if cells[r][c] != center:
                        continue
                    offsets = []
                    for dr, dc in neigh:
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < R and 0 <= cc < C and cells[rr][cc] == fill:
                            offsets.append((dr, dc))
                    if len(offsets) > best_count:
                        best_count = len(offsets)
                        best_pair = (center, fill)
                        best_offsets = offsets[:]

    if not best_pair or best_count <= 0:
        return [row[:] for row in grid]

    center, fill = best_pair

    # Apply motif to every center occurrence
    out_cells = [row[:] for row in cells]
    for r in range(R):
        for c in range(C):
            if cells[r][c] == center:
                for dr, dc in best_offsets:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < R and 0 <= cc < C and out_cells[rr][cc] == bg:
                        out_cells[rr][cc] = fill

    # Reconstruct full grid
    out = [row[:] for row in grid]
    for r, (r0, r1) in enumerate(row_groups):
        for c, (c0, c1) in enumerate(col_groups):
            val = out_cells[r][c]
            for i in range(r0, r1 + 1):
                for j in range(c0, c1 + 1):
                    out[i][j] = val

    return out

